const riftSoldierSheet=new Image();riftSoldierSheet.assetSrc='assets/rift-soldier-v2.png';
function beginRiftSoldier(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'riftRiposte',bespoke:true,windup:2,origin:{x:e.x,y:e.y},counter:false,fired:false,angle:Math.atan2(p.y-e.y,p.x-e.x),length:0};}
function riftSoldierLane(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,along=dx*Math.cos(a.angle)+dy*Math.sin(a.angle),side=-dx*Math.sin(a.angle)+dy*Math.cos(a.angle);return along>=0&&along<=a.length+1e-8&&Math.abs(side)<=24+1e-8&&lineClear(a.origin,point);}
const riftSoldierHitBase=hit;hit=(e,d)=>{let a=e.attack,hp=e.hp,direct=!e.dotTick,result=riftSoldierHitBase(e,d);if(e.species==='r11e2'&&direct&&Number.isFinite(d)&&d>0&&e.hp>0&&e.hp<hp&&e.attack===a&&a?.pattern==='riftRiposte'&&!a.counter&&!a.fired&&e.elapsed<=1&&!paused&&!dead&&!(e.reactionStun>0)&&dist(e,a.origin)<=24){a.counter=true;a.windup=Math.round((e.elapsed+.8)*1e6)/1e6;a.angle=Math.atan2(p.y-a.origin.y,p.x-a.origin.x);for(let distance=5;distance<=350;distance+=5){let q={x:a.origin.x+Math.cos(a.angle)*distance,y:a.origin.y+Math.sin(a.angle)*distance};if(!passable(q.x,q.y,0)||!lineClear(a.origin,q))break;a.length=distance;}e.facing=Math.cos(a.angle)-Math.sin(a.angle)<0?-1:1;playSound('impact',e.x,e.y);}return result;};
const riftSoldierAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e2')return riftSoldierAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='riftRiposte'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=220&&clear){beginRiftSoldier(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,95*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=a.windup){a.fired=true;e.struck=true;if(a.counter?riftSoldierLane(a,p):dist(a.origin,p)<=130&&lineClear(a.origin,p))hurt(a.counter?110:60);playSound('impact',e.x,e.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const riftSoldierDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e2'||!riftSoldierSheet.complete||!riftSoldierSheet.naturalWidth||!riftSoldierSheet.naturalHeight)return riftSoldierDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='riftRiposte')f={row:2,col:e.elapsed<a.windup?(a.counter||e.elapsed>1?1:0):e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=riftSoldierSheet.naturalWidth/4,sh=riftSoldierSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=[[.86,.86,.86,.86],[.8,.8,.8,.8],[.77,.77,.77,.77]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,riftSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(riftSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const riftSoldierSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e2'?175:riftSoldierSizeBase(e);
const riftSoldierGroundBase=drawGroundEffects;drawGroundEffects=()=>{riftSoldierGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e2'):enemies)){let a=e.attack;if(e.species!=='r11e2'||e.hp<=0||a?.pattern!=='riftRiposte'||e.elapsed>a.windup+.3||!visibleAt(e.x,e.y))continue;if(!a.counter){groundRing(e.x,e.y,130,'#a7b0c8',2);if(e.elapsed<=1)groundRing(e.x,e.y,32,'#deb66c',3);continue;}let ux=Math.cos(a.angle),uy=Math.sin(a.angle),end={x:a.origin.x+ux*a.length,y:a.origin.y+uy*a.length};ctx.save();ctx.beginPath();[[a.origin.x-uy*24,a.origin.y+ux*24],[end.x-uy*24,end.y+ux*24],[end.x+uy*24,end.y-ux*24],[a.origin.x+uy*24,a.origin.y-ux*24]].forEach(([x,y],i)=>{let q=project(x,y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fillStyle=a.fired?'rgba(224,169,255,.4)':'rgba(180,106,220,.15)';ctx.strokeStyle='#dfacfa';ctx.lineWidth=2;ctx.fill();ctx.stroke();ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e2',animateEnemy,drawRegionEnemy);
